import concurrent.futures
from datetime import datetime
import json
from pathlib import Path
import re
import subprocess
import time

runs = (45106030437, 45106161986, 45106051239)
base = "0ae1a69261c3fca12bad8bb62021f5fce8d6db2c"
out = Path(__file__).resolve().parent
cache_pattern = re.compile(
    r"Cache restored from key|Cache hit occurred|Cache not found|No cache found|"
    r"Cache saved with key|Cache hit on|cache-hit|Cache Size:", re.I
)

def gh(*args):
    return subprocess.check_output(["gh", *args], text=True, timeout=90)

def timestamp(value):
    return datetime.fromisoformat(value.replace("Z", "+00:00"))

def collect(run):
    result = json.loads(gh("run", "view", str(run), "--json",
        "attempt,conclusion,createdAt,headSha,jobs,status,url"))
    if result["headSha"] != base:
        raise RuntimeError(f"Run {run} checked a different source")
    (out / f"followup-run-{run}.json").write_text(json.dumps(result, indent=2) + "\\n")
    if result["status"] != "completed":
        return None
    jobs = [j for j in result["jobs"] if j["conclusion"] != "skipped"
            and j["startedAt"] and j["completedAt"]]
    start = timestamp(result["createdAt"])
    seconds = lambda value: round(value.total_seconds())
    stats = {"run": run, "conclusion": result["conclusion"], "url": result["url"],
             "observedJobs": len(jobs), "failedJobs": [], "cacheLines": []}
    if jobs:
        first = min(timestamp(j["startedAt"]) for j in jobs)
        end = max(timestamp(j["completedAt"]) for j in jobs)
        stats.update(dispatchToLastCompletionSeconds=seconds(end-start),
                     firstJobToLastCompletionSeconds=seconds(end-first),
                     runnerMinutes=round(sum(seconds(timestamp(j["completedAt"])
                         - timestamp(j["startedAt"])) for j in jobs)/60, 1))
    for job in jobs:
        done = seconds(timestamp(job["completedAt"]) - start)
        if job["conclusion"] == "failure":
            stats["failedJobs"].append({"name": job["name"], "completionSeconds": done})
        if job["name"] == "checks (ubuntu-latest)":
            stats["linuxAggregate"] = {"conclusion": job["conclusion"], "seconds": done}
        if run == runs[-1] or not any(
                "cache" in step["name"].lower() for step in job["steps"]):
            continue
        try:
            log = gh("run", "view", str(run), "--job", str(job["databaseId"]), "--log")
            stats["cacheLines"].extend(line for line in log.splitlines()
                                      if cache_pattern.search(line))
        except (subprocess.SubprocessError, OSError) as error:
            stats.setdefault("cacheLogErrors", []).append(f"{job['name']}: {error}")
    return stats

completed = {}
deadline = time.monotonic() + 5 * 3600
with concurrent.futures.ThreadPoolExecutor() as pool:
    while len(completed) < len(runs) and time.monotonic() < deadline:
        tasks = {pool.submit(collect, run): run for run in runs if run not in completed}
        for task in concurrent.futures.as_completed(tasks):
            try:
                result = task.result()
                if result:
                    completed[tasks[task]] = result
            except (subprocess.SubprocessError, OSError) as error:
                print(error, flush=True)
        (out / "followup-hosted-results.json").write_text(
            json.dumps(list(completed.values()), indent=2) + "\\n")
        if len(completed) < len(runs):
            time.sleep(60)
if len(completed) < len(runs):
    raise SystemExit("Hosted runs still outstanding after five hours")
